package com.garmentstore.auth.domain;
import jakarta.persistence.*; import lombok.*; import java.time.Instant;
@Getter @Setter @Builder @NoArgsConstructor @AllArgsConstructor @Entity @Table(name="login_attempts", indexes={@Index(name="idx_login_attempts_user",columnList="user_id"),@Index(name="idx_login_attempts_identifier",columnList="email_or_mobile"),@Index(name="idx_login_attempts_time",columnList="attempted_at")}) public class LoginAttempt { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id") private User user; @Column(name="email_or_mobile",length=180) private String emailOrMobile; @Enumerated(EnumType.STRING) @Column(name="attempt_type",nullable=false,length=40) private LoginAttemptType attemptType; @Column(name="success",nullable=false) private boolean success; @Column(name="attempted_at",nullable=false) private Instant attemptedAt; @Column(name="ip_address",length=80) private String ipAddress; @Column(name="user_agent",length=500) private String userAgent; @PrePersist void prePersist(){this.attemptedAt=Instant.now();} }
